// 규칙 신호는 학습 입력에서 제외하고 별도의 안전 정책에서 처리한다.
export const exclusions = new Set([2,5,18,19]);
// 회로가 살펴볼 복합 신호 쌍을 고정한다.
export const pairs = [[3,9],[0,1],[8,11],[16,17],[7,9],[10,14]];
// 단계 정의를 편집 가능한 관측 벡터로 바꾼다.
export function vector(values) {
 return signals.map((_,i)=>values[i] ?? 0);
}
// 즉시 정책의 메시지를 점수 계산보다 우선한다.
export function policy(x) {
 if(x[19]>=.9) return "공식 출입 통제가 확인된 가상 구간입니다. 진입 후보에서 제외합니다.";
 if(x[18]>=.9) return "낙상과 미응답이 감지된 가상 상황입니다. 구조 절차 확인이 우선입니다.";
 if(x[5]>=.9) return "가상 낙뢰 경보가 있습니다. 점수와 별개로 산행 중단 안내가 우선입니다.";
 if(x[2]>=.9) return "몸 상태 확인이 필요한 증상이 신고됐습니다. 점수와 별개로 상태 확인을 우선합니다.";
 return "";
}
